// Canonical URL and social-sharing tags of a page. Pure: Layout.astro only prints what this returns, and every URL is
// built from the configured `site`, so moving to another domain is a one-line change in astro.config.mjs.
import type { Locale } from '../../i18n/locales';

// Generated by scripts/generate-brand-assets.mjs from src/assets/brand/.
export const DEFAULT_SHARE_IMAGE = { path: '/og-default.png', width: 1200, height: 630 } as const;

const ogLocale: Record<Locale, string> = { es: 'es_EC', en: 'en_US' };

// A file has an extension in its last segment; pages are folders in the static build and are served with a slash.
const HAS_EXTENSION = /\.[a-z0-9]+$/i;

export function absoluteUrl(site: URL, value: string): string {
	return new URL(value, site).href;
}

// The page's own URL: absolute, without query or hash, and with the trailing slash the static build serves.
export function canonicalUrl(site: URL, pathname: string): string {
	const path = pathname.split(/[?#]/)[0] || '/';
	const normalized = path.endsWith('/') || HAS_EXTENSION.test(path) ? path : `${path}/`;
	return new URL(normalized, new URL(site.origin)).href;
}

export interface SocialMetaInput {
	site: URL;
	pathname: string;
	locale: Locale;
	title: string;
	description: string;
	siteName: string;
	// Share image of the page (absolute or site-relative). Without one, the brand's default is used.
	image?: string;
	type?: 'website' | 'article';
}

export function buildSocialMeta({
	site,
	pathname,
	locale,
	title,
	description,
	siteName,
	image,
	type = 'website',
}: SocialMetaInput) {
	const canonical = canonicalUrl(site, pathname);
	return {
		canonical,
		url: canonical,
		siteName,
		title,
		description,
		type,
		locale: ogLocale[locale],
		alternateLocales: (Object.keys(ogLocale) as Locale[])
			.filter((code) => code !== locale)
			.map((code) => ogLocale[code]),
		image: absoluteUrl(site, image ?? DEFAULT_SHARE_IMAGE.path),
		// Only the default image has known dimensions; a page's own picture (Cloudinary) is declared by URL alone.
		imageSize: image ? undefined : { width: DEFAULT_SHARE_IMAGE.width, height: DEFAULT_SHARE_IMAGE.height },
		twitterCard: 'summary_large_image' as const,
	};
}
